package br.com.mathinclui.auth.aluno;

import br.com.mathinclui.aluno.domain.Aluno; import br.com.mathinclui.aluno.repository.AlunoRepository; import br.com.mathinclui.auth.api.AuthProblemException; import br.com.mathinclui.auth.token.RefreshTokenService; import org.junit.jupiter.api.Test; import org.springframework.security.crypto.password.PasswordEncoder; import java.util.Optional; import static org.assertj.core.api.Assertions.assertThatThrownBy; import static org.mockito.Mockito.*;
class AlunoAuthServiceTest {
 @Test void shouldRejectInactiveStudentWithGenericMessage(){var repository=mock(AlunoRepository.class);var aluno=mock(Aluno.class);when(aluno.isAtivo()).thenReturn(false);when(repository.findByUsernameIgnoreCase("joao")).thenReturn(Optional.of(aluno));var service=new AlunoAuthService(repository,mock(PasswordEncoder.class),mock(RefreshTokenService.class));assertThatThrownBy(()->service.login(new AlunoLoginRequest("joao","4821"))).isInstanceOf(AuthProblemException.class).hasMessage("Credenciais inválidas.");}
 @Test void shouldRejectWrongPin(){var repository=mock(AlunoRepository.class);var encoder=mock(PasswordEncoder.class);var aluno=mock(Aluno.class);when(aluno.isAtivo()).thenReturn(true);when(aluno.getPinHash()).thenReturn("hash");when(repository.findByUsernameIgnoreCase("joao")).thenReturn(Optional.of(aluno));when(encoder.matches("4821","hash")).thenReturn(false);var service=new AlunoAuthService(repository,encoder,mock(RefreshTokenService.class));assertThatThrownBy(()->service.login(new AlunoLoginRequest("joao","4821"))).isInstanceOf(AuthProblemException.class).hasMessage("Credenciais inválidas.");}
 @Test void shouldIssueSessionForCorrectPin(){var repository=mock(AlunoRepository.class);var encoder=mock(PasswordEncoder.class);var refresh=mock(RefreshTokenService.class);var aluno=mock(Aluno.class);when(aluno.isAtivo()).thenReturn(true);when(aluno.getId()).thenReturn(11L);when(aluno.getNome()).thenReturn("João");when(aluno.getUsername()).thenReturn("joao");when(aluno.getPinHash()).thenReturn("hash");when(repository.findByUsernameIgnoreCase("joao")).thenReturn(Optional.of(aluno));when(encoder.matches("4821","hash")).thenReturn(true);var service=new AlunoAuthService(repository,encoder,refresh);service.login(new AlunoLoginRequest("joao","4821"));verify(refresh).issuePair(org.mockito.ArgumentMatchers.argThat(principal->principal.id().equals(11L)&&principal.subjectType()==br.com.mathinclui.auth.security.SubjectType.ALUNO&&principal.role().equals("ROLE_ALUNO")));}
}
